<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import type { SettlementDelivery } from '@/api/propertySettlements'
import PropertyPartyPicker from '@/components/property/PropertyPartyPicker.vue'
import PropertyInstantInput from '@/components/property/PropertyInstantInput.vue'
import DateInput from '@/components/ui/DateInput.vue'
import { settlementInput as input } from './settlementForm'
defineProps<{ supplier: number; labels?: Record<number, string> }>()
const model = defineModel<SettlementDelivery>({ required: true }), { t } = useI18n()
function pending() { if (model.value.status === 'pending') Object.assign(model.value, { delivered_to_id: null, delivered_at: null, method: null, delivery_evidence: '' }) }
</script>
<template><div class="space-y-3"><div class="grid gap-3 sm:grid-cols-2"><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.issuedTo') }}<PropertyPartyPicker v-model="model.issued_to_id" :supplier-id="supplier" :selected-label="labels?.[model.issued_to_id]" /></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.deliveryStatus') }}<select v-model="model.status" :class="input" data-field="delivery-status" @change="pending"><option value="pending">{{ t('propertySettlements.dossier.pending') }}</option><option value="delivered">{{ t('propertySettlements.dossier.delivered') }}</option></select></label></div><template v-if="model.status === 'delivered'"><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.deliveredTo') }}<PropertyPartyPicker v-model="model.delivered_to_id" :supplier-id="supplier" :selected-label="model.delivered_to_id ? labels?.[model.delivered_to_id] : ''" /></label><PropertyInstantInput :model-value="model.delivered_at || ''" :label="t('propertySettlements.dossier.deliveredAt')" required data-field="delivered-at" @update:model-value="model.delivered_at = $event || null" /><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.method') }}<select v-model="model.method" :class="input" required><option :value="null">{{ t('propertySettlements.choose') }}</option><option v-for="v in ['data_box','post','personal','other'] as const" :key="v" :value="v">{{ t(`propertySettlements.dossier.methods.${v}`) }}</option></select></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.receiptEvidence') }}<input v-model="model.delivery_evidence" :class="input" required data-field="delivery-evidence" /></label></template><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.recipientAuthority') }}<input v-model="model.recipient_evidence" :class="input" :required="model.issued_to_id !== model.recipient_id || (model.delivered_to_id !== null && model.delivered_to_id !== model.recipient_id)" /></label><div class="grid gap-3 sm:grid-cols-2"><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.due') }}<DateInput :class="input" v-model="model.due.date" data-field="delivery-due" @update:model-value="if (!$event) { model.due.date = null; model.due.basis_ref = '' }" /></label><label class="flex min-w-0 flex-col gap-1 text-sm">{{ t('propertySettlements.dossier.dueBasis') }}<input v-model="model.due.basis_ref" :class="input" :required="!!model.due.date" :disabled="!model.due.date" /></label></div></div></template>
